def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    for r, c in points:
        for dc in (-1, 0, 1):
            if 0 <= c + dc < w:
                out[r][c + dc] = 8
    return out
